import{_ as e,m as d,k as o,ah as a}from"./chunks/framework.HEc25T99.js";const m=JSON.parse('{"title":"Utilities","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"developers/development/utilities.md","filePath":"src/en/developers/development/utilities.md"}'),c={name:"developers/development/utilities.md"};function r(s,t,n,i,l,u){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="utilities" tabindex="-1">Utilities <a class="header-anchor" href="#utilities" aria-label="Permalink to &quot;Utilities&quot;">​</a></h1><p>Alongside <a href="./sections-widgets.html">sections and widgets</a> and <a href="./content-models.html">content models</a>, Creopse exposes two levels of API that a component can consume: <strong>composables</strong> (Vue) / <strong>hooks</strong> (React) that give access to platform data (<code>@creopse/vue</code>/<code>@creopse/react</code>), and <strong>pure utility functions</strong> shared by both stacks (<code>@creopse/utils</code>).</p><div class="tip custom-block"><p class="custom-block-title">Vue vs React</p><p>Composables/hooks share the same name and signature across both stacks — only the syntax differs. On Vue, <code>const { tr } = useHelper()</code> returns values directly usable in the template (no <code>.value</code> to manage for functions, only for the few <code>Ref</code>s documented below). On React, everything is usable as-is, with no unwrapping needed. Anything coming from <code>@creopse/utils</code> (<code>formatDate</code>, <code>hexToRgba</code>...) is strictly identical on both stacks.</p></div><h2 id="available-composables-hooks" tabindex="-1">Available composables / hooks <a class="header-anchor" href="#available-composables-hooks" aria-label="Permalink to &quot;Available composables / hooks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Composable / Hook</th><th>Role</th></tr></thead><tbody><tr><td><code>useHelper()</code></td><td>Cross-cutting functions: translation, file/link resolution, responsive breakpoints, active language.</td></tr><tr><td><code>useContent()</code></td><td>Page, section, content model, and base information data.</td></tr><tr><td><code>useMenu()</code></td><td>Reading menus and their items, link resolution.</td></tr><tr><td><code>useNews()</code></td><td>Articles, categories, tags, and comments (news).</td></tr><tr><td><code>useVideo()</code></td><td>Video categories and items.</td></tr><tr><td><code>useNewsletter()</code></td><td>Newsletter subscription by email or phone.</td></tr><tr><td><code>useApi()</code></td><td>Generic HTTP requests to the API.</td></tr><tr><td><code>useProps()</code></td><td>Reactive props of the current page (Inertia).</td></tr><tr><td><code>useConfig()</code></td><td>Plugin configuration (base URL, locale...).</td></tr></tbody></table><h2 id="usehelper" tabindex="-1"><code>useHelper()</code> <a class="header-anchor" href="#usehelper" aria-label="Permalink to &quot;`useHelper()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>tr</code></td><td><code>(data, lang?) =&gt; string</code></td><td>Translates an <code>i18n-text</code> field.</td></tr><tr><td><code>rHtml</code></td><td><code>(data, lang?) =&gt; string</code></td><td>Translates and resolves an <code>i18n-editor</code> field (always through <code>v-html</code>/<code>dangerouslySetInnerHTML</code>).</td></tr><tr><td><code>fileUrl</code></td><td><code>(path) =&gt; string</code></td><td>Absolute URL of a file (<code>storage/&lt;path&gt;</code>).</td></tr><tr><td><code>getImage</code></td><td><code>(path, size?) =&gt; Promise&lt;string&gt;</code></td><td>URL of the requested thumbnail (<code>small</code>/<code>medium</code>/<code>large</code>/<code>original</code>), falling back to the original if missing.</td></tr><tr><td><code>getVideoThumbnail</code></td><td><code>(path) =&gt; string</code></td><td>URL of a video&#39;s thumbnail.</td></tr><tr><td><code>resolveUrl</code></td><td><code>(path) =&gt; string</code></td><td>Resolves a relative path to the API&#39;s base URL.</td></tr><tr><td><code>openLink</code></td><td><code>(entity) =&gt; void</code></td><td>Opens a link (menu id, raw URL, or Inertia route) — see <a href="./sections-widgets.html#links-and-cta-buttons">Links and CTA buttons</a>.</td></tr><tr><td><code>languages</code></td><td><code>Language[]</code></td><td>Available languages (<code>fr</code>, <code>en</code>).</td></tr><tr><td><code>updateLang</code></td><td><code>(val, reload?, updateUserPrefs?) =&gt; Promise&lt;void&gt;</code></td><td>Changes the active language.</td></tr><tr><td><code>socialNetworks</code></td><td><code>{ name; icon }[]</code></td><td>List of supported social networks (Header/Footer loop).</td></tr><tr><td><code>detectSocialNetwork</code></td><td><code>(url) =&gt; { name; icon } | null</code></td><td>Detects the social network of a URL.</td></tr><tr><td><code>isXlScreen</code> / <code>isLgScreen</code> / <code>isMdScreen</code> / <code>isSmScreen</code> / <code>is2XlScreen</code></td><td><code>Ref&lt;boolean&gt;</code> (Vue)</td><td>Common responsive breakpoints.</td></tr><tr><td><code>currentRoutePath</code></td><td><code>Ref&lt;string&gt;</code> (Vue)</td><td>Current Inertia page path.</td></tr><tr><td><code>displayFormErrors</code></td><td><code>(errors, displayError) =&gt; void</code></td><td>Displays form errors through a callback.</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>getActiveLanguage()</code> (used for a language selector&#39;s current value) is <strong>not</strong> provided by <code>useHelper()</code> — on Vue it&#39;s a function auto-imported from <code>laravel-vue-i18n</code>.</p></div><h2 id="usecontent" tabindex="-1"><code>useContent()</code> <a class="header-anchor" href="#usecontent" aria-label="Permalink to &quot;`useContent()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>getSectionRootData</code></td><td><code>(key?) =&gt; any</code></td><td>A section&#39;s singleton fields (equivalent to <code>getSectionData(key)?.index</code>).</td></tr><tr><td><code>getSectionData</code></td><td><code>(key?) =&gt; any</code></td><td>A section&#39;s full data (singletons + collections).</td></tr><tr><td><code>getSectionSettings</code></td><td><code>(key?) =&gt; any</code></td><td>A section&#39;s display settings.</td></tr><tr><td><code>getSectionSettingsGroup</code> / <code>getSectionSetting</code></td><td><code>(key?, group, name?) =&gt; any</code></td><td>A specific settings group or setting.</td></tr><tr><td><code>getAnySectionData</code></td><td><code>(sectionSlug, pageSlug, linkId?) =&gt; Promise&lt;any&gt;</code></td><td>A section&#39;s data from any page.</td></tr><tr><td><code>getContentModel</code></td><td><code>(name) =&gt; ContentModelModel | undefined</code></td><td>Content model by name.</td></tr><tr><td><code>getContentModelItems</code></td><td><code>(name, activeOnly?) =&gt; Promise&lt;ContentModelItemModel[]&gt;</code></td><td>Content model items — see <a href="./content-models.html">Content Models</a>.</td></tr><tr><td><code>getPaginatedContentModelItems</code></td><td><code>(name, page, pageSize, activeOnly?, query?, dataFilters?, sortBy?, sortDirection?) =&gt; Promise&lt;PaginatedContentModelItems&gt;</code></td><td>Paginated items, with filters.</td></tr><tr><td><code>submitUserContentModelItem</code></td><td><code>(title, contentModelId, singletonsData?, collectionsData?, onSuccess?, onError?) =&gt; Promise&lt;Response&gt;</code></td><td>Submits a user item (forms).</td></tr><tr><td><code>getContentPath</code></td><td><code>(item, force?) =&gt; string</code></td><td>Permalink path of an item or article.</td></tr><tr><td><code>getAppInformationValue</code></td><td><code>(key, type?) =&gt; any</code></td><td>A base information value (see the table below).</td></tr><tr><td><code>pageData</code></td><td><code>PageModel | null</code></td><td>Current page data.</td></tr><tr><td><code>contentModelItem</code></td><td><code>ContentModelItemModel | null</code></td><td>Current content model item (detail page).</td></tr><tr><td><code>newsArticle</code> / <code>newsCategory</code> / <code>newsTag</code></td><td>—</td><td>Current news article/category/tag.</td></tr><tr><td><code>appPrimaryColor</code> / <code>appSecondaryColor</code> / <code>appAccentColor</code></td><td><code>string</code></td><td>Configured brand colors.</td></tr><tr><td><code>logo</code> / <code>icon</code></td><td><code>string</code></td><td>Configured logo / icon URL.</td></tr></tbody></table><h3 id="getappinformationvalue-keys" tabindex="-1"><code>getAppInformationValue</code> keys <a class="header-anchor" href="#getappinformationvalue-keys" aria-label="Permalink to &quot;`getAppInformationValue` keys&quot;">​</a></h3><p>Never recreate a section field for one of these values — consume them directly through <code>getAppInformationValue(&#39;&lt;key&gt;&#39;)</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>name, icon, oneColorIcon, logo, oneColorLogo, phone, email, address, postalCode,</span></span>\n<span class="line"><span>description, primaryColor, secondaryColor, accentColor, facebook, twitter, instagram,</span></span>\n<span class="line"><span>whatsapp, linkedin, youtube, pinterest, snapchat, tiktok, telegram, discord, reddit,</span></span>\n<span class="line"><span>tumblr, vimeo, twitch, github, dribbble, behance, medium, stackOverflow, threads,</span></span>\n<span class="line"><span>messenger, playstore, appstore, additionalInfo</span></span></code></pre></div><p>These values are managed through <a href="./../resources/cli.html#creopse-base-info-alias-info"><code>creopse base-info</code></a>.</p><h2 id="usemenu" tabindex="-1"><code>useMenu()</code> <a class="header-anchor" href="#usemenu" aria-label="Permalink to &quot;`useMenu()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>getMenu</code></td><td><code>(name, activeOnly?, nested?) =&gt; MenuModel | undefined</code></td><td>Menu by name.</td></tr><tr><td><code>getMenuByLocation</code></td><td><code>(name, activeOnly?, nested?) =&gt; MenuModel | undefined</code></td><td>Menu by location.</td></tr><tr><td><code>getMenuItems</code></td><td><code>(name, visibleOnly?, nested?) =&gt; MenuItemModel[]</code></td><td>Items of a menu by name.</td></tr><tr><td><code>getMenuItemsByLocation</code></td><td><code>(name, visibleOnly?, nested?) =&gt; MenuItemModel[]</code></td><td>Items by location — the most used for a Header/Footer.</td></tr><tr><td><code>getMenuItemById</code></td><td><code>(id) =&gt; MenuItemModel | undefined</code></td><td>Item by id.</td></tr><tr><td><code>getMenuGroups</code> / <code>getMenuItemsByGroup</code> / <code>getMenuGroupedItems</code> / <code>getMenuUngroupedItems</code></td><td>—</td><td>Grouping items (dropdowns).</td></tr><tr><td><code>getMenuHref</code></td><td><code>(item) =&gt; string</code></td><td>Resolved <code>href</code> of a menu item.</td></tr><tr><td><code>openMenu</code></td><td><code>(item?) =&gt; void</code></td><td>Navigates to a menu item based on its <code>targetType</code>.</td></tr><tr><td><code>getLinkFromMenuItemId</code></td><td><code>(id) =&gt; string</code></td><td>Link resolved from a <code>menu-item-link</code> field.</td></tr></tbody></table><p>See the full rendering pattern in <a href="./sections-widgets.html#links-and-cta-buttons">Links and CTA buttons</a>.</p><h2 id="usenews" tabindex="-1"><code>useNews()</code> <a class="header-anchor" href="#usenews" aria-label="Permalink to &quot;`useNews()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>isLoading</code></td><td><code>Ref&lt;boolean&gt;</code></td><td>Loading state.</td></tr><tr><td><code>loadArticles</code></td><td><code>(params: { pageSize, page?, query?, status?, categories?, tags?, months? }) =&gt; Promise&lt;{ articles; meta }&gt;</code></td><td>Paginated articles.</td></tr><tr><td><code>loadCategories</code> / <code>loadTags</code></td><td><code>(filterByIsVisible?) =&gt; Promise&lt;[]&gt;</code></td><td>Visible categories/tags.</td></tr><tr><td><code>loadArticlesMonths</code></td><td><code>() =&gt; Promise&lt;string[]&gt;</code></td><td>Months with articles (archives).</td></tr><tr><td><code>loadArticlesCount</code> / <code>loadArticlesCountByStatus</code> / <code>loadArticlesCountByAuthor</code></td><td>—</td><td>Article counters.</td></tr><tr><td><code>loadComments</code></td><td><code>(params: { pageSize, page?, query? }) =&gt; Promise&lt;{ comments; meta }&gt;</code></td><td>Paginated comments.</td></tr><tr><td><code>addComment</code></td><td><code>(comment, onSuccess?, onError?) =&gt; Promise&lt;Response&gt;</code></td><td>Adds a comment.</td></tr></tbody></table><p>Always go through this composable for a list of articles — never a section collection, see <a href="./sections-widgets.html">Sections &amp; Widgets</a>.</p><h2 id="usevideo" tabindex="-1"><code>useVideo()</code> <a class="header-anchor" href="#usevideo" aria-label="Permalink to &quot;`useVideo()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>isLoading</code></td><td><code>Ref&lt;boolean&gt;</code></td><td>Loading state.</td></tr><tr><td><code>loadCategories</code></td><td><code>(filterByIsVisible?) =&gt; Promise&lt;VideoCategoryModel[]&gt;</code></td><td>Video categories.</td></tr><tr><td><code>loadVideoItems</code></td><td><code>(params) =&gt; Promise&lt;PaginatedVideoItems&gt;</code></td><td>Paginated videos.</td></tr></tbody></table><h2 id="usenewsletter" tabindex="-1"><code>useNewsletter()</code> <a class="header-anchor" href="#usenewsletter" aria-label="Permalink to &quot;`useNewsletter()`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Member</th><th>Signature</th><th>Description</th></tr></thead><tbody><tr><td><code>isLoading</code></td><td><code>Ref&lt;boolean&gt;</code></td><td>Loading state.</td></tr><tr><td><code>subscribeEmail</code></td><td><code>(email, onSuccess?, onError?) =&gt; Promise&lt;void&gt;</code></td><td>Subscribes an email.</td></tr><tr><td><code>subscribePhone</code></td><td><code>(phone, onSuccess?, onError?) =&gt; Promise&lt;void&gt;</code></td><td>Subscribes a phone number (spaces stripped).</td></tr></tbody></table><p>Typical usage pattern in a Footer: see <a href="./sections-widgets.html">Sections &amp; Widgets</a>.</p><h2 id="useapi-useprops-useconfig" tabindex="-1"><code>useApi()</code>, <code>useProps()</code>, <code>useConfig()</code> <a class="header-anchor" href="#useapi-useprops-useconfig" aria-label="Permalink to &quot;`useApi()`, `useProps()`, `useConfig()`&quot;">​</a></h2><ul><li><strong><code>useApi()</code></strong> — low-level methods (<code>request</code>, <code>getItemRequest</code>, <code>postItemRequest</code>, <code>putItemRequest</code>, <code>deleteItemRequest</code>, <code>getAllItemsRequest</code>, <code>handleError</code>) for HTTP calls outside the scope of the domain composables above.</li><li><strong><code>useProps()</code></strong> — returns the page&#39;s reactive props (Inertia data). Used to access <code>contentModelItem</code>/<code>article</code> on a detail page, see <a href="./content-models.html#consuming-a-content-model">Content Models</a>.</li><li><strong><code>useConfig()</code></strong> — returns the plugin configuration (<code>apiBaseUrl</code>, <code>apiUrl</code>, <code>locale</code>, <code>fallbackLocale</code>, <code>debug</code>...).</li></ul><h2 id="utility-components" tabindex="-1">Utility components <a class="header-anchor" href="#utility-components" aria-label="Permalink to &quot;Utility components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Vue</th><th>React</th></tr></thead><tbody><tr><td>Image with thumbnail selection</td><td><code>&lt;Image :src=&quot;...&quot; size=&quot;large&quot; /&gt;</code></td><td><code>&lt;Image src={...} size=&quot;large&quot; /&gt;</code></td></tr><tr><td>Image resolved by a promise</td><td><code>&lt;AsyncImg :load=&quot;...&quot; /&gt;</code></td><td><code>&lt;AsyncImg load={...} /&gt;</code></td></tr><tr><td>Portal/modal (no JSX equivalent to <code>&lt;Teleport&gt;</code>)</td><td><code>&lt;Teleport to=&quot;body&quot;&gt;</code> (native Vue)</td><td><code>&lt;MountedTeleport to=&quot;body&quot;&gt;</code></td></tr><tr><td>Transition/animation</td><td><code>&lt;Transition name=&quot;...&quot;&gt;</code> (native Vue)</td><td><code>&lt;CustomTransition name=&quot;fade|slide-fade|bounce&quot;&gt;</code></td></tr><tr><td>SVG icon of an <code>icon</code> field (data stored in the database)</td><td><code>&lt;ContentIcon :data=&quot;...&quot; :size=&quot;42&quot; /&gt;</code></td><td><code>&lt;ContentIcon data={...} size={42} /&gt;</code> (<code>@arkn/react-icon-picker</code>)</td></tr><tr><td>Static icon (MDI, Bootstrap Icons...)</td><td><code>&lt;Icon icon=&quot;mdi:...&quot; /&gt;</code></td><td><code>&lt;Icon icon=&quot;mdi:...&quot; /&gt;</code> (<code>@iconify/react</code>)</td></tr><tr><td>Sticky bar</td><td><code>&lt;StickyTop&gt;</code> / <code>&lt;StickyBottom&gt;</code></td><td><code>&lt;StickyTop&gt;</code> / <code>&lt;StickyBottom&gt;</code></td></tr><tr><td>Text truncation with &quot;read more&quot;</td><td><code>&lt;ReadMore :text=&quot;...&quot; /&gt;</code></td><td><code>&lt;ReadMore text={...} /&gt;</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>On React, every component used in JSX must be <strong>explicitly imported</strong> at the top of the file (<code>Image</code> from <code>@creopse/react</code>, <code>Icon</code> from <code>@iconify/react</code>...) — unlike the Vue examples where some Creopse components are registered globally by the plugin.</p></div><h2 id="pure-utility-functions-creopse-utils" tabindex="-1">Pure utility functions (<code>@creopse/utils</code>) <a class="header-anchor" href="#pure-utility-functions-creopse-utils" aria-label="Permalink to &quot;Pure utility functions (`@creopse/utils`)&quot;">​</a></h2><p>Shared by both stacks, importable from <code>@creopse/utils</code> or <code>@creopse/utils/helpers</code>.</p><h3 id="dates" tabindex="-1">Dates <a class="header-anchor" href="#dates" aria-label="Permalink to &quot;Dates&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>formatDate(date, { outPattern?, locale? })</code></td><td>Formats a date — <strong>the helper to use for any date display in a section</strong>, rather than a local <code>toLocaleDateString</code>.</td></tr><tr><td><code>reformatDate(date, { inPattern?, outPattern?, locale? })</code></td><td>Converts a date from one format to another.</td></tr><tr><td><code>differenceFromNow(date, { locale?, pattern? })</code></td><td>Relative difference (&quot;3 days ago&quot;).</td></tr><tr><td><code>differenceWithToday(date, { pattern?, unit? })</code></td><td>Difference between a date and today.</td></tr><tr><td><code>differenceBetweenDates(start, end, options?)</code></td><td>Difference between two dates.</td></tr><tr><td><code>getDateFromTimestamp(date, options?)</code></td><td>Formats a UNIX timestamp (seconds) into a date.</td></tr><tr><td><code>getCurrentTimestamp()</code></td><td>Current UNIX timestamp.</td></tr></tbody></table><h3 id="colors" tabindex="-1">Colors <a class="header-anchor" href="#colors" aria-label="Permalink to &quot;Colors&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>hexToRgba(hex, alpha)</code></td><td>Converts a hex color into <code>rgba(...)</code> — returns the complete string directly, not separate components.</td></tr><tr><td><code>genRandomColor()</code></td><td>Generates a random hex color.</td></tr></tbody></table><h3 id="strings" tabindex="-1">Strings <a class="header-anchor" href="#strings" aria-label="Permalink to &quot;Strings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>capitalizeFirstLetter(string)</code></td><td>Capitalizes the first letter.</td></tr><tr><td><code>getNameInitials(name)</code></td><td>Initials (2 letters) of a full name.</td></tr><tr><td><code>extractNumber(string, options?)</code></td><td>Extracts one or more numbers from a string.</td></tr><tr><td><code>isTitleLike(value, options?)</code> / <code>extractTitleLike(data, tr, defaultValue?)</code></td><td>Heuristic &quot;title-like&quot; field detection.</td></tr><tr><td><code>replaceStringParts(str, replacements)</code></td><td>Replaces several parts of a string based on a dictionary.</td></tr></tbody></table><h3 id="numbers-and-arrays" tabindex="-1">Numbers and arrays <a class="header-anchor" href="#numbers-and-arrays" aria-label="Permalink to &quot;Numbers and arrays&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>getRandomInteger(min, max)</code></td><td>Inclusive random integer.</td></tr><tr><td><code>abbreviateNumber(number)</code></td><td>Abbreviates a number (<code>1.2k</code>, <code>3.4M</code>...).</td></tr><tr><td><code>removeDuplicates(arr, property)</code></td><td>Deduplicates an array by a property.</td></tr><tr><td><code>shuffleArray(array)</code></td><td>Shuffles an array (Fisher-Yates).</td></tr></tbody></table><h3 id="files-images-and-urls" tabindex="-1">Files, images, and URLs <a class="header-anchor" href="#files-images-and-urls" aria-label="Permalink to &quot;Files, images, and URLs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>humanFileSize(bytes, si?, dp?)</code></td><td>Human-readable file size.</td></tr><tr><td><code>getFileExtension(path)</code></td><td>Extension of a file path.</td></tr><tr><td><code>compressImage(file, options?)</code></td><td>Compresses an image client-side.</td></tr><tr><td><code>isExternal(path)</code></td><td>True if the path is an external URL, a <code>mailto:</code>, or a <code>tel:</code>.</td></tr><tr><td><code>isURL(str)</code></td><td>Validates that a string is a URL.</td></tr><tr><td><code>removeTrailingSlash</code> / <code>removeLeadingSlash</code></td><td>Path cleanup.</td></tr></tbody></table><h3 id="misc" tabindex="-1">Misc <a class="header-anchor" href="#misc" aria-label="Permalink to &quot;Misc&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Function</th><th>Description</th></tr></thead><tbody><tr><td><code>sleep(ms)</code></td><td>Waits the given number of milliseconds.</td></tr><tr><td><code>formatTimeFromSeconds(duration, options?)</code></td><td>Formats a duration as <code>HH:MM:SS</code>.</td></tr><tr><td><code>slideToId(id)</code></td><td>Smooth-scrolls to an element.</td></tr><tr><td><code>getDistanceFromLatLonInKm(lat1, lon1, lat2, lon2)</code></td><td>Distance between two coordinates (Haversine).</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This list covers the functions most useful when building sections. <code>@creopse/utils</code> also exposes enums, domain models, and shared types (<code>ContentModelItemModel</code>, <code>MenuItemModel</code>, <code>AppInformationKey</code>...) consumed internally by the composables above.</p></div>',45)])])}const g=e(c,[["render",r]]);export{m as __pageData,g as default};
